module game_solver (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] N,\n    input wire [11:0] numbers [0:3],\n    output reg [3:0] count,\n    output reg done\n);\n    \n    // State encoding\n    localparam [3:0] IDLE         = 4'd0;\n    localparam [3:0] INIT_START   = 4'd1;\n    localparam [3:0] BUILD_LINEAR = 4'd2;\n    localparam [3:0] SPECIAL_CASE = 4'd3;\n    localparam [3:0] DP_INIT      = 4'd4;\n    localparam [3:0] DP_LOOP      = 4'd5;\n    localparam [3:0] DP_DONE      = 4'd6;\n    localparam [3:0] INCREMENT_START = 4'd7;\n    localparam [3:0] FINISHED     = 4'd8;\n    \n    reg [3:0] state, next_state;\n    \n    // Internal registers\n    reg [2:0] current_start_index;\n    reg [3:0] count_reg;\n    \n    // Linear array registers\n    reg [11:0] B0, B1, B2;\n    reg [1:0] L;\n    \n    // DP table registers (signed)\n    reg signed [5:0] dp00, dp11, dp22, dp01, dp12, dp02;\n    \n    // DP loop counters\n    reg [1:0] current_length;\n    reg [1:0] inner_index;\n    \n    // Helper function: odd\n    function automatic [0:0] is_odd;\n        input [11:0] num;\n        begin\n            is_odd = num[0];\n        end\n    endfunction\n    \n    // Helper function: max of two signed 6-bit numbers\n    function automatic signed [5:0] max6;\n        input signed [5:0] a, b;\n        begin\n            max6 = (a > b) ? a : b;\n        end\n    endfunction\n    \n    // State transition and output logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            current_start_index <= 3'd0;\n            count_reg <= 4'd0;\n            B0 <= 12'd0;\n            B1 <= 12'd0;\n            B2 <= 12'd0;\n            L <= 2'd0;\n            dp00 <= 6'sd0;\n            dp11 <= 6'sd0;\n            dp22 <= 6'sd0;\n            dp01 <= 6'sd0;\n            dp12 <= 6'sd0;\n            dp02 <= 6'sd0;\n            current_length <= 2'd0;\n            inner_index <= 2'd0;\n            count <= 4'd0;\n            done <= 1'b0;\n        end else begin\n            state <= next_state;\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        count_reg <= 4'd0;\n                        current_start_index <= 3'd0;\n                    end\n                end\n                \n                BUILD_LINEAR: begin\n                    // Build linear array for current_start_index\n                    if (N > 2'd1) L <= N - 3'd1;\n                    else L <= 2'd0;\n                    \n                    case (N)\n                        4'd1: begin\n                            // No linear array\n                        end\n                        4'd2: begin\n                            case (current_start_index)\n                                3'd0: B0 <= numbers[4'd1];\n                                3'd1: B0 <= numbers[4'd0];\n                                default: ;\n                            endcase\n                        end\n                        4'd3: begin\n                            case (current_start_index)\n                                3'd0: begin B0 <= numbers[4'd1]; B1 <= numbers[4'd2]; end\n                                3'd1: begin B0 <= numbers[4'd2]; B1 <= numbers[4'd0]; end\n                                3'd2: begin B0 <= numbers[4'd0]; B1 <= numbers[4'd1]; end\n                                default: ;\n                            endcase\n                        end\n                        4'd4: begin\n                            case (current_start_index)\n                                3'd0: begin B0 <= numbers[4'd1]; B1 <= numbers[4'd2]; B2 <= numbers[4'd3]; end\n                                3'd1: begin B0 <= numbers[4'd2]; B1 <= numbers[4'd3]; B2 <= numbers[4'd0]; end\n                                3'd2: begin B0 <= numbers[4'd3]; B1 <= numbers[4'd0]; B2 <= numbers[4'd1]; end\n                                3'd3: begin B0 <= numbers[4'd0]; B1 <= numbers[4'd1]; B2 <= numbers[4'd2]; end\n                                default: ;\n                            endcase\n                        end\n                    endcase\n                end\n                \n                SPECIAL_CASE: begin\n                    if (is_odd(numbers[current_start_index]))\n                        count_reg <= count_reg + 4'd1;\n                end\n                \n                DP_INIT: begin\n                    if (L >= 2'd1) dp00 <= is_odd(B0) ? 6'sd1 : 6'sd0;\n                    if (L >= 2'd2) dp11 <= is_odd(B1) ? 6'sd1 : 6'sd0;\n                    if (L >= 2'd3) dp22 <= is_odd(B2) ? 6'sd1 : 6'sd0;\n                    current_length <= 2'd2;\n                    inner_index <= 2'd0;\n                end\n                \n                DP_LOOP: begin\n                    if (current_length == 2'd2) begin\n                        case (inner_index)\n                            2'd0: begin\n                                if (L >= 2'd2)\n                                    dp01 <= max6( (is_odd(B0) - dp11), (is_odd(B1) - dp00) );\n                            end\n                            2'd1: begin\n                                if (L >= 2'd3)\n                                    dp12 <= max6( (is_odd(B1) - dp22), (is_odd(B2) - dp11) );\n                            end\n                        endcase\n                    end else if (current_length == 2'd3) begin\n                        if (inner_index == 2'd0 && L >= 2'd3)\n                            dp02 <= max6( (is_odd(B0) - dp12), (is_odd(B2) - dp01) );\n                    end\n                    \n                    inner_index <= inner_index + 2'd1;\n                end\n                \n                DP_DONE: begin\n                    reg signed [5:0] dp_value;\n                    case (L)\n                        2'd1: dp_value = dp00;\n                        2'd2: dp_value = dp01;\n                        2'd3: dp_value = dp02;\n                        default: dp_value = 6'sd0;\n                    endcase\n                    if ((is_odd(numbers[current_start_index]) ? 6'sd1 : 6'sd0) - dp_value > 6'sd0)\n                        count_reg <= count_reg + 4'd1;\n                end\n                \n                FINISHED: begin\n                    count <= count_reg;\n                    done <= 1'b1;\n                end\n            endcase\n        end\n    end\n    \n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = INIT_START;\n            INIT_START: next_state = BUILD_LINEAR;\n            BUILD_LINEAR: begin\n                if (N == 4'd1) next_state = SPECIAL_CASE;\n                else next_state = DP_INIT;\n            end\n            SPECIAL_CASE: next_state = INCREMENT_START;\n            DP_INIT: begin\n                if (L == 2'd1) next_state = DP_DONE;\n                else next_state = DP_LOOP;\n            end\n            DP_LOOP: begin\n                if ((current_length > L) || (current_length == 2'd3 && inner_index >= L - 2'd2))\n                    next_state = DP_DONE;\n                else\n                    next_state = DP_LOOP;\n            end\n            DP_DONE: next_state = INCREMENT_START;\n            INCREMENT_START: begin\n                if (current_start_index + 3'd1 >= N)\n                    next_state = FINISHED;\n                else\n                    next_state = BUILD_LINEAR;\n            end\n            FINISHED: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\nendmodule